let damageFade=0,damageArrowFade=0;function updatePlayerHud(){const r=THREE.MathUtils.clamp(player.hp/player.maxHp,0,1);hpNumber.textContent=Math.ceil(player.hp);hpFill.style.width=`${r*100}%`;requestAnimationFrame(()=>hpGhost.style.width=`${r*100}%`);hpFill.style.background=r>.55?"#dff7ff":r>.28?"#ffb14f":"#ff4655";playerHud.style.borderColor=r<.3?"rgba(255,70,85,.27)":"rgba(255,255,255,.10)";}function showDamageDirection(source){const dx=source.x-player.position.x,dz=source.z-player.position.z,worldAngle=Math.atan2(dx,dz),relative=worldAngle-yaw;damageArrow.style.transform=`translate(-50%,-50%) rotate(${relative}rad)`;damageArrow.style.opacity="1";damageArrowFade=.36;}function damagePlayer(amount,source){if(player.dead)return;player.hp=Math.max(0,player.hp-amount);updatePlayerHud();damageVignette.style.opacity=".82";damageFade=.28;showDamageDirection(source);hurtSound();shakePower=Math.min(1,shakePower+.28);if(player.hp<=0)die();}function die(){player.dead=true;mouseHeld=false;if(document.pointerLockElement)document.exitPointerLock();deathScreen.classList.add("show");stateElement.textContent="DOWN";}
