function updateEnemies(dt){for(const e of enemies){if(!e.alive){if(e.dying){e.deathT+=dt;const q=Math.min(1,e.deathT/.42),ease=1-Math.pow(1-q,3);e.root.rotation.z=-ease*1.2;e.root.position.y=-ease*.24;e.root.scale.setScalar(1-ease*.12);e.materials.forEach(m=>{m.transparent=true;m.opacity=1-q*.78;});if(q>=1)e.dying=false;}continue;}e.hpBar.group.quaternion.copy(camera.quaternion);e.bob+=dt*2.2;const dx=player.position.x-e.root.position.x,dz=player.position.z-e.root.position.z,dist=Math.hypot(dx,dz)||.001,nx=dx/dist,nz=dz/dist;e.root.rotation.y=Math.atan2(dx,dz);e.strafeTimer-=dt;if(e.strafeTimer<=0){e.strafe*=-1;e.strafeTimer=.65+Math.random()*1.1;}let mx=0,mz=0;if(dist>e.preferred+.65){mx+=nx;mz+=nz;}else if(dist<e.preferred-1){mx-=nx*.8;mz-=nz*.8;}else{mx+=-nz*e.strafe*.8;mz+=nx*e.strafe*.8;}for(const o of enemies){if(o===e||!o.alive)continue;const sx=e.root.position.x-o.root.position.x,sz=e.root.position.z-o.root.position.z,sd=Math.hypot(sx,sz);if(sd>0&&sd<1.4){mx+=sx/sd*(1.4-sd);mz+=sz/sd*(1.4-sd);}}const ml=Math.hypot(mx,mz);if(ml>0&&!player.dead){mx/=ml;mz/=ml;moveEnemy(e,mx*e.speed*dt,mz*e.speed*dt);}e.root.position.y=Math.sin(e.bob)*.018;e.attackCooldown-=dt;if(!player.dead&&dist<11&&e.attackCooldown<=0&&hasLineOfSight(e)){spawnEnemyBolt(e);e.attackCooldown=(e.type==="ranger"?.82:e.type==="brute"?1.65:1.25)+Math.random()*.55;}}}

const run={wave:1,state:"combat",nextAt:0,started:false};function waveEnemyCount(w){return Math.min(12,3+w);}function showBanner(big,small=""){banner.querySelector(".big").textContent=big;banner.querySelector(".small").textContent=small;banner.classList.remove("show");void banner.offsetWidth;banner.classList.add("show");}function updateWaveHud(){waveValue.textContent=String(run.wave).padStart(2,"0");const alive=enemies.filter(e=>e.alive).length;waveSub.textContent=run.state==="combat"?`${alive} HOSTILES`:run.state==="intermission"?"NEXT WAVE INBOUND":"STANDBY";}function updateEnemyHud(){const alive=enemies.filter(e=>e.alive).length;enemyHud.innerHTML=`HOSTILES ${alive}<br><span style="opacity:.45">K ${totalKills} · CRIT ${headshotKills}</span>`;updateWaveHud();if(run.started&&run.state==="combat"&&alive===0&&!player.dead){run.state="intermission";run.nextAt=performance.now()+2400;showBanner("WAVE CLEAR",`WAVE ${String(run.wave).padStart(2,"0")} COMPLETE`);updateWaveHud();}}function startWave(w){clearEnemies();for(let i=0;i<waveEnemyCount(w);i++)spawnWaveEnemy(i,w);run.state="combat";run.started=true;showBanner(`WAVE ${String(w).padStart(2,"0")}`,w>=3?"MIXED HOSTILES":"HOSTILES INBOUND");updateEnemyHud();}function updateWave(now){if(run.state==="intermission"&&!player.dead&&now>=run.nextAt){run.wave++;player.hp=Math.min(player.maxHp,player.hp+22);updatePlayerHud();for(const w of Object.values(weapons)){w.ammo=w.maxAmmo;w.reloading=false;}updateWeaponHud();startWave(run.wave);}}
