function resetRun(lockAfter=false){player.dead=false;deathScreen.classList.remove("show");player.position.set(0,0,7);player.velocityY=0;player.grounded=true;player.hp=player.maxHp;yaw=Math.PI;pitch=0;totalKills=0;headshotKills=0;run.wave=1;run.state="combat";run.started=false;for(const b of enemyBolts)scene.remove(b.mesh);enemyBolts.length=0;for(const w of Object.values(weapons)){w.ammo=w.maxAmmo;w.reloading=false;w.reloadStart=w.reloadEnd=0;w.last=-Infinity;w.current=w.spread;}if(currentWeaponId!=="rifle"){models[currentWeaponId].group.visible=false;currentWeaponId="rifle";models[currentWeaponId].group.visible=true;}switching.active=false;mouseHeld=false;updatePlayerHud();updateWeaponHud();startWave(1);syncCamera();if(lockAfter)setTimeout(()=>renderer.domElement.requestPointerLock(),70);}
window.addEventListener("keydown",e=>{keys.add(e.code);if(e.code==="Space"&&!player.dead&&player.grounded&&document.pointerLockElement===renderer.domElement){player.velocityY=player.jumpSpeed;player.grounded=false;}if(e.code==="KeyR")startReload();if(e.code==="Digit1")beginSwitch("rifle");if(e.code==="Digit2")beginSwitch("cannon");if(e.code==="KeyP")openSettings();if(e.code==="KeyT")resetRun();if(e.code==="Enter"&&player.dead)resetRun(true);});window.addEventListener("keyup",e=>keys.delete(e.code));window.addEventListener("blur",()=>{keys.clear();mouseHeld=false;});window.addEventListener("mousedown",e=>{if(e.button!==0||player.dead)return;mouseHeld=true;if(!currentWeapon().automatic)fire();});window.addEventListener("mouseup",e=>{if(e.button===0)mouseHeld=false;});startButton.onclick=()=>{audio();renderer.domElement.requestPointerLock();};renderer.domElement.onclick=()=>{audio();if(!player.dead&&document.pointerLockElement!==renderer.domElement&&!settingsPanel.classList.contains("show"))renderer.domElement.requestPointerLock();};document.addEventListener("pointerlockchange",()=>{const locked=document.pointerLockElement===renderer.domElement;startScreen.classList.toggle("hidden",locked||player.dead);if(!locked){keys.clear();mouseHeld=false;}});document.addEventListener("mousemove",e=>{if(player.dead||document.pointerLockElement!==renderer.domElement)return;const s=.00205*settings.sensitivity;yaw-=e.movementX*s;pitch-=e.movementY*s;pitch=THREE.MathUtils.clamp(pitch,-Math.PI/2+.02,Math.PI/2-.02);});restartButton.onclick=()=>resetRun(true);
let fpsTime=0,fpsFrames=0;const clock=new THREE.Clock();function loop(){requestAnimationFrame(loop);const dt=Math.min(clock.getDelta(),.05),now=performance.now();if(!player.dead&&document.pointerLockElement===renderer.domElement){updateMovement(dt);if(mouseHeld&&!switching.active&&currentWeapon().automatic)fire();}updateReload(now);const drop=updateSwitch(now);updateWeapon(dt,now,drop);updateCamera(dt);updateEnemies(dt);updateBolts(dt);updateTransient(dt);updateWave(now);if(damageFade>0){damageFade-=dt;if(damageFade<=0)damageVignette.style.opacity="0";}if(damageArrowFade>0){damageArrowFade-=dt;if(damageArrowFade<=0)damageArrow.style.opacity="0";}syncCamera();fpsTime+=dt;fpsFrames++;if(fpsTime>=.5){fpsElement.textContent=`FPS: ${Math.round(fpsFrames/fpsTime)}`;fpsTime=0;fpsFrames=0;}stateElement.textContent=player.dead?"DOWN":player.grounded?"GROUND":"AIR";renderer.render(scene,camera);}resetRun();loop();window.addEventListener("resize",()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,2));});